window.products.push({"id":777984,"name":"Japanese Geisha Oriental Fan Polish Glass Christmas Ornament","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/81V49KFv7UL._AC_SL1500_.jpg","description":"Bring a memory of Japan into your home this Christmas and let this hand blown ornament brighten up your tree.Bright red with a branch of cherry blossoms which are so revered in Japan. Folding fans have been in Japan since their invention in the 10th century They came to Europe via the trade with China in the 15th centuryFor over 20 years Dariusz and Ewa Kowalczyk have been making beautiful hand blown glass ornaments in their studio in Czestochowa Poland. They have grown into a large production facility employing dozens of skilled glass blowers and painters making each ornament a unique decoration for your Christmas tree.","images":["https://m.media-amazon.com/images/I/81V49KFv7UL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Coppenrath","source_asin":"B075QJNWBQ","category_path":"Home & Kitchen"},"sku":"BM-777984","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B075QJNWBQ","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B075QJNWBQ","price_pending":true,"merchant_ready":false});
